insert into targets (id, name, simple_explanation, detailed_explanation) values ('12780b83-a9fa-5bac-ac70-02e67f53af18', 'PSMA', 'A protein found on the surface of prostate cancer cells that drugs can use as a homing beacon.', 'Prostate-specific membrane antigen — a cell-surface glycoprotein highly overexpressed on prostate cancer cells, used as a targeting antigen for T-cell engagers and radioligand therapies.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('c34005c3-2f35-5543-9e4a-6fae4185d00a', 'PLK1', 'An enzyme cancer cells rely on to divide; blocking it can stop tumor growth.', 'Polo-like kinase 1 — a serine/threonine kinase essential for mitotic entry and progression, frequently overexpressed in RAS-mutated tumors.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('cfac407f-7af2-5245-a65e-2dfe718c3c5a', 'Pan-RAS', 'A family of proteins that, when mutated, act like a stuck gas pedal telling cells to keep growing.', 'The RAS family of GTPases (KRAS/NRAS/HRAS) — oncogenic mutations lock RAS in its active, GTP-bound state, continuously signaling through MAPK/PI3K pathways. ''Pan-RAS'' therapies aim to hit multiple RAS mutants at once rather than one specific hotspot.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('3bf4dfb1-24e6-5ff1-aca5-5fa637f70c51', 'KRAS', 'The most commonly mutated cancer-driving gene; drugs targeting it aim to shut off its growth signal.', 'Kirsten rat sarcoma viral oncogene homolog — the most frequently mutated RAS-family member across human cancers, with hotspot mutations (G12C, G12D, G12V) each requiring differently-shaped inhibitors.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('2a75068f-dbf1-59fd-9fa8-2448eab6ab63', 'PKC', 'A signaling enzyme that, when mutated upstream, drives a rare eye cancer called uveal melanoma.', 'Protein kinase C — acts downstream of the GNAQ/GNA11 mutations that define most uveal melanomas, making PKC a druggable node in that pathway.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('8ec58a9a-5294-55e4-818d-d25490653f3b', 'DLL3', 'A protein found almost exclusively on certain lung cancer cells, making it a precise drug target.', 'Delta-like ligand 3 — a Notch pathway inhibitory ligand aberrantly expressed on the cell surface of small cell lung cancer and other neuroendocrine tumors, with minimal expression on healthy tissue.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('824bc0cb-db0a-5afd-a041-9b467b1266ae', 'PI3Kalpha', 'A growth-signaling enzyme that''s frequently mutated in breast cancer.', 'Phosphoinositide 3-kinase alpha — encoded by PIK3CA, one of the most commonly mutated oncogenes in HR+/HER2- breast cancer; mutant-selective inhibitors aim to spare the wild-type enzyme elsewhere in the body.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('654f299b-bd12-5d95-94ed-78b9abe29cac', 'NRAS', 'A RAS-family gene that drives a subset of melanomas and other solid tumors when mutated.', 'Neuroblastoma RAS viral oncogene homolog — a RAS-family GTPase; NRAS-mutant cancers have historically lacked a selective inhibitor because NRAS''s binding pocket differs subtly from KRAS''s.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('9b7746a8-2da6-5088-8659-973343777264', 'ROS1', 'A growth-signal receptor that, when fused to another gene, can drive lung cancer.', 'ROS proto-oncogene 1 receptor tyrosine kinase — gene fusions create a constitutively active kinase that drives a molecular subset of non-small cell lung cancer.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('67b5c18d-ed97-5792-87c9-19575acc9ec8', 'IDH1', 'A metabolism enzyme that, when mutated, produces a byproduct that helps brain tumors grow.', 'Isocitrate dehydrogenase 1 — hotspot mutations (e.g. R132H) produce the oncometabolite 2-hydroxyglutarate, defining a molecular subtype of glioma.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('f837106f-6e69-50c7-9f59-054603c0ffc4', 'Menin', 'A protein certain leukemia cells depend on to keep growing abnormally.', 'Menin (MEN1 gene product) — an epigenetic scaffolding protein required for the leukemogenic gene-expression program in NPM1-mutant and KMT2A-rearranged AML; blocking its interaction with KMT2A shuts that program down.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('c0168e36-53ea-5367-9da5-d61af04d8346', 'Farnesyltransferase', 'An enzyme that anchors other proteins to the cell membrane so they can signal; blocking it can misdirect cancer-driving proteins.', 'Farnesyltransferase — catalyzes farnesylation, a lipid modification required for membrane localization of RAS and related GTPases; inhibiting it is being explored to weaken RAS-pathway signaling and overcome resistance to other targeted therapies.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('ea4043ee-aef0-5029-af4b-dfaf44bf2c72', 'WEE1', 'A checkpoint enzyme that gives cancer cells time to repair DNA damage before dividing; blocking it can force damaged cells to divide and die.', 'WEE1 kinase — a cell-cycle checkpoint regulator that inhibits CDK1; particularly relevant in tumors already deficient in other DNA-damage-response pathways, such as Cyclin E1-amplified cancers.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('d7dfb3c8-b1e6-505d-a49a-2681645525df', 'ENPP3', 'A protein highly abundant on kidney cancer cells, used to direct immune cells to attack them.', 'Ectonucleotide pyrophosphatase/phosphodiesterase 3 — highly expressed on clear cell renal cell carcinoma; used as the tumor-binding arm of a T-cell-engaging bispecific antibody.') on conflict (name) do nothing;
insert into targets (id, name, simple_explanation, detailed_explanation) values ('3fcfe6f8-9856-5b97-b638-8b9771eb8ccf', 'CLDN6', 'A protein found almost exclusively on certain reproductive-system tumors, not on healthy adult tissue.', 'Claudin-6 — a tight-junction protein normally restricted to fetal development, re-expressed on gynecologic and germ cell tumors, making it an attractive target with minimal on-target, off-tumor risk.') on conflict (name) do nothing;
